		/** 
		 * Tests creating a new Experiment.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Experiment");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Experiment" );

			try {            
				Experiment entity = ExperimentService.getExperimentInstance().createExperiment( generateNewEntity() );
				thePrimaryKey = entity.getExperimentId();
				LOGGER.info( "-- Successfully created a Experiment with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Experiment. 
		 */
		public Experiment testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Experiment" );

			Experiment entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Experiment with primary key" );
			msg.append( thePrimaryKey );
			
			ExperimentFetchOneSummary fetchOneSummary = new ExperimentFetchOneSummary( thePrimaryKey );

			try {
				entity = ExperimentService.getExperimentInstance().getExperiment( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Experiment " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Experiment.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Experiment." );

			StringBuilder msg = new StringBuilder( "Failed to update a Experiment : " );        
			Experiment entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Experiment." );

				// for use later on...
				thePrimaryKey = entity.getExperimentId();

				ExperimentService proxy = ExperimentService.getExperimentInstance();            
				proxy.updateExperiment( entity );   

				LOGGER.info( "-- Successfully saved Experiment - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Experiment.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Experiment." );

			try{
			    Experiment entity = testRead(); 
				ExperimentService.getExperimentInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Experiment with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Experiment with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Experiments.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Experiments:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Experiment : " );        
			List<Experiment> collection  = null;

			try {
				// call the static get method on the ExperimentService
				collection = ExperimentService.getExperimentInstance().getAllExperiment();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Experiment entity = null;            
					Iterator<Experiment> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getExperimentId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

